PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Swamp_Women dbr:Tracy_Rides }

  # get the director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }

  # get the director's birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
}
LIMIT 100

